INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e98d3645-974c-467f-8c0d-3795da6595fe', 'cb3f5f83-4dee-48a1-944d-4820530113be', 0, 'This is Annualized Loss Expectancy (ALE) — calculated as Single Loss Expectancy (SLE, the monetary loss from ONE occurrence — here $500,000, the asset''s full value) multiplied by the Annualized Rate of Occurrence (ARO, how many times per year the event is expected to happen — here 0.20, since a 20% annual chance equates to an ARO of 0.2), giving ALE = $500,000 × 0.20 = $100,000 per year; this quantitative approach expresses risk in concrete financial terms, distinct from a QUALITATIVE risk assessment, which instead uses relative categories like High/Medium/Low without assigning specific dollar figures.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be007761-586c-4f53-9a79-9ef704573f86', 'cb3f5f83-4dee-48a1-944d-4820530113be', 1, 'This is a risk register, since risk registers are specifically defined as the formula multiplying Single Loss Expectancy by the Annualized Rate of Occurrence.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc6ca84a-3df9-435b-9d6b-5c8e8a6359ed', 'cb3f5f83-4dee-48a1-944d-4820530113be', 2, 'This is a gap analysis, since gap analyses are specifically defined as calculating an asset''s Single Loss Expectancy multiplied by its Annualized Rate of Occurrence.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00956f8f-4f71-40fa-80ec-0f9cb176b8f2', 'cb3f5f83-4dee-48a1-944d-4820530113be', 3, 'Risk can never be meaningfully expressed in specific quantitative dollar terms; only qualitative High/Medium/Low categories are ever used in risk assessment.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca66de53-2f09-46f6-b4a9-bb6892af53cf', '10fe7152-90ce-4bd7-99e6-7389a6f32e81', 0, 'Security through obscurity — relying on the secrecy of a system''s design or implementation details as the PRIMARY or SOLE protection mechanism, rather than on genuinely robust, independently-verifiable security controls; this is considered a flawed sole strategy specifically because once the obscured details are discovered (through reverse engineering, an insider leak, or independent research — a real, common occurrence), NO underlying protection remains at all, whereas obscurity used as one MINOR, additional layer alongside genuinely robust controls (defense-in-depth, covered in a prior paper) is a different, more defensible use of the same underlying idea.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7c71210-c007-45bb-90f5-711d079c333f', '10fe7152-90ce-4bd7-99e6-7389a6f32e81', 1, 'Defense-in-depth, since defense-in-depth is specifically defined as relying solely on undisclosed technical details as a system''s only protection mechanism.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8612059c-6b77-4c17-b697-833c90fae095', '10fe7152-90ce-4bd7-99e6-7389a6f32e81', 2, 'Zero Trust, since Zero Trust is specifically defined as relying on the secrecy of a system''s design as its primary and sole security control.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da0f1fd7-0d84-41e9-b0a4-ea26d79724f7', '10fe7152-90ce-4bd7-99e6-7389a6f32e81', 3, 'Keeping technical implementation details undisclosed provides no risk of any kind and is always an equally valid, complete security strategy on its own.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2b52a7e-6913-4b1e-8ea6-8ca12bbbe2e1', '751ae6b1-916d-45ca-a2f3-c7288a56af03', 0, 'ARP poisoning (also called ARP spoofing) — sending forged ARP messages on a local network segment to associate the attacker''s own MAC address with a legitimate IP address (typically the default gateway), causing other devices on that segment to unknowingly send their traffic to the attacker''s machine instead of its real intended destination, putting the attacker in a genuine on-path position to intercept, inspect, or modify that traffic — a Layer 2-specific mechanism distinct from DNS poisoning (covered in a prior paper, which manipulates DOMAIN-NAME resolution rather than local network address mapping).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cab633a4-4c2e-4810-b26c-20d78b4ac693', '751ae6b1-916d-45ca-a2f3-c7288a56af03', 1, 'DNS poisoning, since DNS poisoning is specifically defined as forging ARP messages to associate an attacker''s MAC address with a legitimate gateway IP address on a local network segment.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57955344-3063-4b06-aad9-870b54c895ae', '751ae6b1-916d-45ca-a2f3-c7288a56af03', 2, 'A logic bomb, since logic bombs are defined as forging Layer 2 ARP messages to redirect a victim''s local network traffic through an attacker''s machine.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b65a68ff-6768-4057-aa02-0a539a62407f', '751ae6b1-916d-45ca-a2f3-c7288a56af03', 3, 'ARP messages cannot be forged or manipulated by an attacker under any circumstance; a device''s ARP table always reflects only genuine, accurate network information.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c15afca7-ca48-4cd7-b481-946c14c73bb4', '94100aed-9d17-4cb7-b121-acc193a752bc', 0, 'Directory traversal (also called path traversal) — occurs when an application uses unsanitized user input to construct a file system path, allowing an attacker to include sequences like "../" to navigate OUTSIDE the intended, restricted directory and access arbitrary files elsewhere on the file system that were never meant to be reachable through the application at all, a genuinely different mechanism and target from SQL injection (covered in a prior paper, which manipulates a DATABASE query rather than a file system PATH).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e882ddc5-4c9a-4a84-aa79-2d9353dbc763', '94100aed-9d17-4cb7-b121-acc193a752bc', 1, 'CSRF, since CSRF is defined as using unsanitized user input to construct a file system path and access files outside the intended directory.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b93d377-eb36-4a78-8fe6-7a77e543f93b', '94100aed-9d17-4cb7-b121-acc193a752bc', 2, 'A buffer overflow, since buffer overflows are defined as using directory-traversal sequences like "../" to access arbitrary files outside an application''s intended directory.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('051d494f-aed0-4187-8325-23e3af790b7d', '94100aed-9d17-4cb7-b121-acc193a752bc', 3, 'This scenario is not a realistic vulnerability, since a web application can never be tricked into reading a file outside its own intended directory regardless of user input.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dfc944f-2766-427b-9ae0-836c23db56f9', '2ffe54a9-7ab0-4d06-9330-21968b055449', 0, 'SPF, DKIM, and DMARC — SPF (Sender Policy Framework) publishes which mail servers are authorized to send email for a domain; DKIM (DomainKeys Identified Mail) cryptographically signs outgoing messages so receivers can verify they genuinely came from the claimed domain and weren''t altered in transit; and DMARC (Domain-based Message Authentication, Reporting & Conformance) tells receiving mail servers what to actually DO (reject, quarantine, or allow) when a message fails SPF/DKIM checks — together, these three records let a receiving mail server reject email falsely claiming to be from a domain that never actually sent it.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13a7e362-8078-4f2c-8749-7dde0fa894e6', '2ffe54a9-7ab0-4d06-9330-21968b055449', 1, 'MFA, since MFA is the standard DNS record type that specifies which mail servers are authorized to send email on a domain''s behalf.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c007b46-7665-45e3-b21c-cc978e9a7da5', '2ffe54a9-7ab0-4d06-9330-21968b055449', 2, 'IOCs, since IOCs are the DNS records that cryptographically sign outgoing email and specify enforcement action for messages that fail authentication.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6eebfeb2-a2c1-4de6-a5e9-cf5cf71dbfc8', '2ffe54a9-7ab0-4d06-9330-21968b055449', 3, 'No DNS-based mechanism exists to verify whether an email claiming to be from a specific domain genuinely originated from that domain''s authorized mail servers.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eaf6efcd-4973-4195-87cd-086f219bd053', 'eaeb9645-fffb-4976-b4cc-cca47041dc1f', 0, 'Full-disk encryption, file-level encryption, and field-level (or column-level) database encryption — full-disk encryption protects against physical device theft specifically (the whole drive is unreadable without the decryption key, but offers no protection once the device is unlocked and running) while file-level and field-level encryption instead protect SPECIFIC data regardless of where it''s copied or which broader system it lives within, at the cost of more granular key/access management complexity — the right granularity depends on the specific threat being addressed, not a one-size-fits-all choice.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0e897d8-8ed6-4a21-bd5b-446ede744318', 'eaeb9645-fffb-4976-b4cc-cca47041dc1f', 1, 'These three granularities of encryption are functionally identical, providing the exact same protection against the exact same threats with no meaningful distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52f4a45e-bf04-464c-9103-70eb155a93e9', 'eaeb9645-fffb-4976-b4cc-cca47041dc1f', 2, 'Tokenization, since tokenization is specifically defined as the practice of choosing between full-disk, file-level, and field-level encryption granularity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('354b2b3b-1352-4d46-a8bf-705db218e484', 'eaeb9645-fffb-4976-b4cc-cca47041dc1f', 3, 'Encryption can only ever be applied to an entire storage device at once; encrypting individual files or specific database fields independently is not technically possible.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2109959e-bd6b-4e1b-b8cc-d94b8a7eb916', '41d4e113-08c6-4096-8cc1-4bafde999f1e', 0, 'Tokenization — replaces sensitive data with a randomly generated, non-mathematically-related substitute value (a "token"), with the actual mapping between token and real value stored ONLY in a separate, tightly-controlled vault; this is fundamentally different from encryption, where the protected value CAN always be mathematically derived back from the ciphertext given the correct key — tokenization''s substitute value has NO such mathematical relationship to the original at all, meaning even a compromise of the tokenized data alone (without also separately compromising the vault) reveals nothing computable about the real value, a genuinely stronger property for reducing the SCOPE of systems that need to handle the truly sensitive original data (directly relevant to PCI-DSS compliance scope reduction).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2de5c12-24d4-4868-8f7c-398fe1502248', '41d4e113-08c6-4096-8cc1-4bafde999f1e', 1, 'Tokenization and encryption are functionally and mathematically identical techniques, with a token always being mathematically derivable back to the original value using the correct key, just like ciphertext.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d6103e3-5078-4825-a0fd-346f05b4abf7', '41d4e113-08c6-4096-8cc1-4bafde999f1e', 2, 'A CASB, since CASBs are specifically defined as replacing sensitive data with a randomly generated, non-mathematically-related substitute value stored in a separate vault.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('645eed6d-acca-4699-89a2-d914a838a528', '41d4e113-08c6-4096-8cc1-4bafde999f1e', 3, 'No technique exists for protecting sensitive data other than encryption; storing a substitute value with no mathematical relationship to the original is not technically achievable.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8c0834e-c3d2-4d8f-8c2a-31b91e13e439', '49b4d8c2-cecf-4716-8f95-0139425b629e', 0, 'A CASB (Cloud Access Security Broker) — sits as an enforcement point BETWEEN an organization''s users and the cloud services they access (whether known/sanctioned or discovered "shadow IT" usage, connecting to the attack surface management concept covered in a prior paper), applying consistent security policies (DLP, covered in a prior paper; access control; encryption requirements; visibility into usage) across MULTIPLE cloud services from one central point, rather than requiring separate, inconsistent configuration within each individual SaaS application''s own native settings.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a87604a8-0ae7-45cd-8d6d-28d3efb6482b', '49b4d8c2-cecf-4716-8f95-0139425b629e', 1, 'A bastion host, since bastion hosts are specifically defined as a single enforcement point applying consistent DLP, access control, and encryption policy across multiple third-party cloud SaaS applications.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f54adead-f476-4806-a720-5ef2178df52f', '49b4d8c2-cecf-4716-8f95-0139425b629e', 2, 'An air-gapped network, since air-gapped networks are the standard architecture for centrally enforcing consistent security policy across multiple cloud SaaS applications.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa6a6c61-9649-4906-88cd-9d862e9ccb79', '49b4d8c2-cecf-4716-8f95-0139425b629e', 3, 'No architecture exists for centrally enforcing consistent security policy across multiple third-party cloud services; each SaaS application''s security must always be configured entirely independently with no shared control point.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c55edeb-d375-4d28-9022-75f6a1c1c218', 'ce149368-dd2a-4f25-8ad0-6b442d72bb32', 0, 'An SBOM (Software Bill of Materials) — a complete, itemized inventory of every component (including third-party and open-source libraries, and their specific versions) that makes up a piece of software, letting an organization immediately and accurately determine whether and where a newly-disclosed vulnerability in a specific component actually affects their own products, without needing to manually audit every codebase from scratch each time a new vulnerability disclosure happens — directly relevant to both supply chain attack risk (covered in a prior paper) and the general vulnerability management lifecycle (covered in a prior paper).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fb21430-23fb-4f34-9f50-b0c4c0e77f59', 'ce149368-dd2a-4f25-8ad0-6b442d72bb32', 1, 'A risk register, since risk registers are specifically defined as a complete, itemized inventory of every third-party and open-source software component used in a product.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d7d7847-e082-47a1-9b78-d7e5205d18a9', 'ce149368-dd2a-4f25-8ad0-6b442d72bb32', 2, 'A RACI matrix, since RACI matrices are specifically defined as an itemized inventory of third-party and open-source software components and their specific versions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('823198de-9ccc-480c-8026-d933c8b07010', 'ce149368-dd2a-4f25-8ad0-6b442d72bb32', 3, 'No practical way exists to maintain an inventory of every third-party and open-source component used across a software product; this would always require manually auditing the codebase from scratch for every new vulnerability disclosure.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98ddf2c3-813a-41ab-84e7-97f56243f5db', '7ebb6883-e54d-4377-97f7-1dc42f14f0a9', 0, 'CVSS (Common Vulnerability Scoring System) — a standardized, widely-adopted methodology for scoring a vulnerability''s severity on a consistent 0-to-10 scale, based on factors like the attack vector (network-reachable vs. requiring local/physical access), attack complexity, privileges required, and the impact on confidentiality/integrity/availability if successfully exploited, giving security teams a CONSISTENT, comparable basis for the prioritization decisions covered generally in a prior paper (which also weighs real-world exploitability and asset criticality alongside the raw CVSS score itself).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1db93ae9-27ad-45b1-9710-b9160e1c9ee2', '7ebb6883-e54d-4377-97f7-1dc42f14f0a9', 1, 'IOC, since IOCs are specifically defined as the standardized 0-to-10 methodology for scoring a vulnerability''s severity based on attack vector and impact.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('295ac213-3776-4d6c-9652-640a25cce308', '7ebb6883-e54d-4377-97f7-1dc42f14f0a9', 2, 'RACI, since RACI is specifically defined as the standardized methodology for scoring vulnerability severity based on attack complexity and privileges required.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb393ea3-4c77-4d96-b66d-06c6fb365452', '7ebb6883-e54d-4377-97f7-1dc42f14f0a9', 3, 'No standardized methodology exists for scoring vulnerability severity; every vulnerability scanning tool always assigns severity ratings using its own entirely proprietary, non-comparable scale.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('213b6813-2a45-403c-8dd8-d1ab5869bdf3', 'bcc743e3-ef04-4d95-aa24-861824b20991', 0, 'This is an incremental backup strategy — each day''s backup captures only data changed since the MOST RECENT backup of any kind (full or incremental), making each individual daily backup fast and small, but RESTORATION requires applying the last full backup PLUS every single incremental backup since then, in exact sequential order; this contrasts with a differential backup strategy, which backs up everything changed since the last FULL backup specifically (making each differential backup progressively larger through the week, but restoration only ever needs the last full backup plus the SINGLE most recent differential, a genuinely faster and simpler restore process).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97f4e782-cae1-40bc-bb6c-c2c599179394', 'bcc743e3-ef04-4d95-aa24-861824b20991', 1, 'This is a differential backup strategy, since differential backups are specifically defined as capturing only data changed since the most recent backup of any kind, whether full or partial.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4cb9efd-dacc-438f-919d-cb0a61557548', 'bcc743e3-ef04-4d95-aa24-861824b20991', 2, 'Incremental and differential backup strategies are functionally identical, with no meaningful difference in backup size or restoration process between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf802515-4545-4b68-9170-42d304927e74', 'bcc743e3-ef04-4d95-aa24-861824b20991', 3, 'Backing up only changed data since a prior backup is not technically possible; every backup must always capture a complete copy of all data regardless of what has changed.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('271f8d5d-8c02-404e-b721-01abb9d36ed6', 'c8515f41-3058-40e9-96fe-0b966a66c2b4', 0, 'MTTD (Mean Time To Detect) and MTTR (Mean Time To Respond/Remediate) — MTTD measures the average time between an incident actually beginning and it being detected, a direct measure of DETECTION capability (a longer MTTD means threats are dwelling undetected longer, connecting to the value of threat hunting, covered in a prior paper, in proactively reducing this dwell time); MTTR measures the average time from detection to actual containment/resolution, a direct measure of RESPONSE effectiveness — together, these give leadership concrete, trackable metrics for security operations performance over time, distinct from the general security KPI concept covered in a prior paper by naming these two specific, standard, widely-used metrics.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf10867e-a780-4e65-9835-5a60bde6649b', 'c8515f41-3058-40e9-96fe-0b966a66c2b4', 1, 'RTO and RPO, since RTO and RPO are specifically defined as measuring the average time to detect an incident and the average time from detection to containment.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a34ffefe-1574-42a1-ba85-dd5230a539bd', 'c8515f41-3058-40e9-96fe-0b966a66c2b4', 2, 'SLE and ARO, since SLE and ARO are specifically defined as the average time to detect and the average time to respond to a security incident.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1b716ee-00b8-4838-bf55-97aa3520eb63', 'c8515f41-3058-40e9-96fe-0b966a66c2b4', 3, 'Security operations performance can never be meaningfully measured with concrete, trackable metrics; only qualitative, subjective assessment is possible.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad7a8eff-e898-45ba-a65d-210e5cc27fe5', '0999eb24-aa31-45e4-bd26-3435518ba20d', 0, 'Application allowlisting (also called application whitelisting) — explicitly defines which specific applications/executables are PERMITTED to run on a system, blocking everything else by default, including entirely novel, previously-unseen malware with no existing signature, since the control isn''t based on recognizing something as BAD (the way signature-based antivirus, covered in a prior paper, works) but rather on the software simply not being on the approved list at all — the inverse, and generally more restrictive, approach compared to application denylisting (blacklisting), which instead explicitly blocks only KNOWN-bad software while permitting everything else by default.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a8b9a2f-16a0-4ad6-ab2e-f9eaff516fcc', '0999eb24-aa31-45e4-bd26-3435518ba20d', 1, 'Application denylisting, since denylisting is specifically defined as blocking every application by default except those explicitly pre-approved by IT in advance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0865c149-ef4e-4e4f-a08e-8a107c800e0b', '0999eb24-aa31-45e4-bd26-3435518ba20d', 2, 'NAC, since NAC is specifically defined as blocking every application by default except those explicitly pre-approved by IT, based on the application itself rather than device posture.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2683e75a-717a-483c-8345-d817e8bbb5b5', '0999eb24-aa31-45e4-bd26-3435518ba20d', 3, 'No security technique can block previously-unseen, unknown malware with no existing signature; only known, catalogued threats can ever be blocked by any endpoint control.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8c8d935-9ad7-4ebf-abf8-4c2b24c77a8e', 'c4ebfd0c-ca30-4162-aa78-6692e72eec42', 0, 'OCSP (Online Certificate Status Protocol) — lets a client query a CA''s OCSP responder in real time for the revocation status of ONE SPECIFIC certificate, receiving a direct, targeted answer without needing to download an entire CRL (which lists EVERY revoked certificate for that CA, potentially a large file, covered generally as part of PKI/CA concepts in a prior paper); this is meaningfully faster and more efficient for a single per-connection revocation check, at the trade-off of the OCSP responder itself being a real-time dependency (and, in some implementations, potentially able to observe which specific certificates/sites a given client is checking, a genuine privacy consideration OCSP Stapling was later introduced to address).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f369016-5b7f-4259-869d-c90286f1c35c', 'c4ebfd0c-ca30-4162-aa78-6692e72eec42', 1, 'A CRL, since a CRL is specifically defined as the faster, real-time, per-certificate alternative to querying an OCSP responder.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5a7c891-56ab-4fec-bfc1-3146e82a04de', 'c4ebfd0c-ca30-4162-aa78-6692e72eec42', 2, 'CVSS, since CVSS is the protocol specifically used for real-time, per-certificate revocation status checking as an alternative to downloading a full CRL.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bde722df-7c18-43d3-a5b7-a73f8a5a5778', 'c4ebfd0c-ca30-4162-aa78-6692e72eec42', 3, 'No faster alternative to downloading a complete CRL exists; every certificate revocation check always requires retrieving the full revocation list.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7948ffc-ff7e-49b9-877e-de2af4e61351', '8963ea06-268e-47a9-a458-d2b6bf986b20', 0, 'A false positive (the scanner flagged something that actually isn''t there or isn''t actually a real problem) and a false negative (the scanner missed something that genuinely IS a real problem, giving a false sense of security); false negatives are generally considered the MORE dangerous error type, since a false positive merely wastes investigation time confirming a non-issue, while a false negative leaves a genuine, real vulnerability completely unaddressed and unknown, with the organization believing (incorrectly) that the system is clean.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0aab070d-daa5-47dc-9db7-97f4de21dffa', '8963ea06-268e-47a9-a458-d2b6bf986b20', 1, 'A false negative is when the scanner flags something that isn''t actually there, and a false positive is when the scanner misses a genuinely real vulnerability — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f216c2e-9747-466a-84f6-e55583e488fb', '8963ea06-268e-47a9-a458-d2b6bf986b20', 2, 'False positives and false negatives are two different names for the exact same type of scanning error, with no meaningful distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('924c441b-ec16-4a39-af84-8e7d8decc35f', '8963ea06-268e-47a9-a458-d2b6bf986b20', 3, 'Vulnerability scanning tools are always perfectly accurate and never produce either a false positive or a false negative under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dcc1b73a-2d2e-417f-94aa-9aff9a16286b', 'fcaa62e6-2e1b-40bf-a74e-e0c4b29f2dbc', 0, 'A standard data retention policy sets the ROUTINE, ordinary schedule for how long data is normally kept before deletion (here, 2 years for support tickets) — but a legal hold (covered in a prior paper) is a distinct, EXTERNALLY-TRIGGERED exception that specifically OVERRIDES the routine retention schedule for any data covered by the hold, suspending normal deletion for that specific data until the legal matter concludes, regardless of what the standard schedule would otherwise call for; the two are genuinely complementary policies operating at different times for different reasons, not the same policy under two names.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a643552-29f1-48a8-a457-4d44e4a7666c', 'fcaa62e6-2e1b-40bf-a74e-e0c4b29f2dbc', 1, 'A legal hold and a standard data retention policy are the exact same policy under two different names, with the legal hold having no ability to override the routine retention schedule.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bbe4182b-f9ef-4255-b033-186cb1f8beda', 'fcaa62e6-2e1b-40bf-a74e-e0c4b29f2dbc', 2, 'The routine 2-year retention schedule always continues to govern and delete the affected data on schedule regardless of any pending litigation or legal hold notification.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f21f2f24-b713-407c-a437-816935eba094', 'fcaa62e6-2e1b-40bf-a74e-e0c4b29f2dbc', 3, 'Companies have no obligation of any kind to preserve data differently in response to pending litigation; a legal hold carries no real practical or legal significance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14d97f88-ae30-4b78-8cdb-9bf94a47c2d2', '8c6ed419-88ce-44c7-b7a5-6b049827c92b', 0, 'PCI-DSS (Payment Card Industry Data Security Standard) — an INDUSTRY-established (not government-legislated) security standard specifically governing how organizations that handle cardholder data must store, process, and transmit it, created and enforced by the payment card industry itself (the major card brands and the PCI Security Standards Council) rather than by a government legislative body, distinct from a law like HIPAA (covered in a prior paper, government-enacted, governing health information specifically) or GDPR (covered in a prior paper, a government-enacted EU regulation) — directly connecting to tokenization (covered earlier this paper) as one common, real technique organizations use specifically to reduce their PCI-DSS compliance scope.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b0b789b-891c-4da4-bba4-0ae08ad31512', '8c6ed419-88ce-44c7-b7a5-6b049827c92b', 1, 'HIPAA, since HIPAA is specifically the industry-established (not government-legislated) standard governing how cardholder payment data must be stored, processed, and transmitted.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2e886ad-18f4-4a76-8abb-5b8f381acd92', '8c6ed419-88ce-44c7-b7a5-6b049827c92b', 2, 'GDPR, since GDPR is specifically an industry-established payment card security standard rather than a government-enacted data protection regulation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe52b54e-b5dc-4111-97f5-4deb2cd77258', '8c6ed419-88ce-44c7-b7a5-6b049827c92b', 3, 'No standard or regulatory requirement of any kind governs how organizations that process credit card payments must protect cardholder data.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd1890a7-fbe0-4d6b-9a60-c3a4a88566c1', 'dbe8b55d-6c75-4082-9bab-0da5c43ecf90', 0, 'A whistleblower protection program (often implemented via an anonymous or confidential reporting channel/hotline) — specifically designed to let employees report suspected wrongdoing without fear of retaliation, which is exactly why independence from the normal management chain matters: if reports had to go through an employee''s own direct manager (who might themselves be implicated, or personally motivated to suppress the report to protect their own team/reputation), genuinely serious issues would be far less likely to ever actually surface at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1e76a4a-57ac-424c-b8cf-493712b6f1cb', 'dbe8b55d-6c75-4082-9bab-0da5c43ecf90', 1, 'A BAA (Business Associate Agreement), since BAAs are specifically defined as a confidential channel letting employees report suspected fraud or ethics violations without fear of retaliation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0b3c94f-9455-4fee-8a9e-c5e1aa44913f', 'dbe8b55d-6c75-4082-9bab-0da5c43ecf90', 2, 'A CASB, since CASBs are specifically defined as the confidential, independent reporting channel employees use to report suspected fraud or security incidents.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('714472a6-0493-4cd6-807e-89975db11522', 'dbe8b55d-6c75-4082-9bab-0da5c43ecf90', 3, 'Providing employees a confidential channel to report suspected wrongdoing offers no meaningful organizational or security value and is not a real, standard governance practice.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('444159f2-73dc-424d-98e6-45c46b779d08', '331d6339-1c7f-45da-90fc-4d295bdb2ac0', 0, 'A Business Associate Agreement (BAA) — a legally required contract under HIPAA between a covered entity (like the hospital) and any third party (a "business associate," here the billing company) that will handle protected health information on the covered entity''s behalf, specifically obligating that business associate to appropriately safeguard the health information and outlining permitted uses, required security measures, and breach notification obligations — legally required to be in place BEFORE any protected health information is shared with that third party, not an optional or after-the-fact formality.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14fdb55e-13ea-44cb-a46e-f0563733cd0a', '331d6339-1c7f-45da-90fc-4d295bdb2ac0', 1, 'An MOU, since MOUs are specifically the legally required HIPAA contract type between a covered entity and any third party handling protected health information on its behalf.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a12eae4-243f-4cf4-b47c-ffe297fde3f2', '331d6339-1c7f-45da-90fc-4d295bdb2ac0', 2, 'An SLA, since SLAs are specifically the legally required HIPAA contract type obligating a third party to safeguard protected health information before it can be shared.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9de998b1-17c0-4d7f-8fd5-01bf5cee8457', '331d6339-1c7f-45da-90fc-4d295bdb2ac0', 3, 'HIPAA imposes no contractual requirement of any kind before a covered entity shares protected health information with a third-party business associate.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35a3c195-4ea8-4ecb-8d4d-8fdfc51ebc21', '9c20ea5e-702f-4145-acec-eafd3518ff19', 0, 'Adware (the visible, disruptive category — unwanted advertisements, browser hijacking, unfamiliar toolbars, generally more of a nuisance than a severe security threat on its own) and spyware (the covert, invisible category — silently monitoring and transmitting user activity like browsing habits or keystrokes without the user''s knowledge, a genuinely more serious security and privacy concern precisely because it''s designed to remain undetected rather than announce its presence through obvious symptoms the way adware typically does).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b11a551-baf5-46cb-bb7d-53a0ddbdbee3', '9c20ea5e-702f-4145-acec-eafd3518ff19', 1, 'Spyware is the visible, disruptive category producing pop-up ads and browser hijacking, while adware is the covert category silently tracking and transmitting user activity — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b482f88d-0751-46e0-a292-ed8874f2f309', '9c20ea5e-702f-4145-acec-eafd3518ff19', 2, 'Adware and spyware are two different names for the exact same malware category, with no meaningful distinction in visibility, behavior, or severity between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf764b51-da5c-4dc6-b04e-771ea88075a2', '9c20ea5e-702f-4145-acec-eafd3518ff19', 3, 'Malware can never operate covertly without producing any visible symptoms; every malware infection always announces its presence through obvious, noticeable changes to the system.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
